import{_ as n,c as t,o as i,ah as r}from"./chunks/framework.CAZQ2vdu.js";const a="/Qonnectra-docs/pr-17/images/manual/teil-a/map.jpg",s="/Qonnectra-docs/pr-17/images/manual/teil-a/map_selected_object.jpg",d="/Qonnectra-docs/pr-17/images/manual/teil-a/map_trench_conduits.jpg",l="/Qonnectra-docs/pr-17/images/manual/teil-a/map_trench_cables.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/map_trench_profile.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/map_node_slots.jpg",u="/Qonnectra-docs/pr-17/images/manual/teil-a/map_node_structure.jpg",z=JSON.parse('{"title":"5. Karte","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/05-karte.md","filePath":"manual/teil-a-anwenderhandbuch/05-karte.md"}'),c={name:"manual/teil-a-anwenderhandbuch/05-karte.md"};function b(g,e,m,f,p,k){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_5-karte" tabindex="-1">5. Karte <a class="header-anchor" href="#_5-karte" aria-label="Permalink to &quot;5. Karte&quot;">​</a></h1><p>Die Karte ist eines der zentralen Werkzeuge in Qonnectra. Sie dient der visuellen Darstellung des Netzbestands, der Orientierung im Raum und dem schnellen Aufruf von Informationen zu einzelnen Netzobjekten. Sie erreichen die Karte über die linke Navigationsleiste durch Klicken auf den Menüpunkt „Karte“.</p><p><img src="'+a+'" alt="Screenshot Karte" data-zoomable="true"></p><p>Bewegung, Legende, Transparenz und Suche funktionieren wie in Kapitel <a href="./03-wiederkehrende-bedienelemente.html">Wiederkehrende Bedienelemente</a> beschrieben. Dieses Kapitel behandelt, was nur für die Kartenansicht gilt.</p><h2 id="_5-1-kartenausschnitt-zoomstufe-und-gespeicherte-position" tabindex="-1">5.1 Kartenausschnitt, Zoomstufe und gespeicherte Position <a class="header-anchor" href="#_5-1-kartenausschnitt-zoomstufe-und-gespeicherte-position" aria-label="Permalink to &quot;5.1 Kartenausschnitt, Zoomstufe und gespeicherte Position&quot;">​</a></h2><p>Qonnectra merkt sich den letzten Kartenausschnitt. Wenn Sie die Karte erneut öffnen, sehen Sie wieder die Stelle, an der Sie zuletzt gearbeitet haben.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Das gilt auch über einen Projektwechsel hinweg: Wählen Sie bei geöffneter Karte ein anderes Projekt, bleibt der Ausschnitt stehen und die Karte springt <strong>nicht</strong> in das Gebiet des neuen Projekts. Sie sehen dann unter Umständen eine leere Karte, obwohl das Projekt Daten hat. Holen Sie sich die Daten mit „Auf Ausdehnung zoomen“ beim Legendeneintrag „Adresse“ ins Bild, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a>.</p></div><h2 id="_5-2-layer-der-karte" tabindex="-1">5.2 Layer der Karte <a class="header-anchor" href="#_5-2-layer-der-karte" aria-label="Permalink to &quot;5.2 Layer der Karte&quot;">​</a></h2><p>Welche Layer die Legende führt, welche sich nach Typen aufklappen lassen und wie Sie sie schalten, beschreibt Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> – in der Kartenansicht gilt das unverändert.</p><p>Kartenspezifisch ist nur die Darstellung selbst: Die Farben und Formen der Layer stellen Sie unter „Einstellungen“ ein, siehe Kapitel <a href="./17-einstellungen.html">Einstellungen</a>. Davon hängt auch ab, ob sich der Eintrag „Trasse“ aufklappen lässt.</p><h2 id="_5-3-objekte-auswahlen-und-eigenschaften-lesen" tabindex="-1">5.3 Objekte auswählen und Eigenschaften lesen <a class="header-anchor" href="#_5-3-objekte-auswahlen-und-eigenschaften-lesen" aria-label="Permalink to &quot;5.3 Objekte auswählen und Eigenschaften lesen&quot;">​</a></h2><p>Wenn Sie ein Objekt (z. B. eine Trasse oder einen Netzknoten) auf der Karte anklicken, öffnet sich auf der rechten Seite die <strong>Info-Box</strong>, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-die-info-box-mit-ihren-reitern">Die Info-Box</a>. Welche Reiter sie enthält, hängt von der Objektart ab:</p><ul><li>Trasse: „Eigenschaften“, „Rohrübersicht“, „Kabelübersicht“, „Aktionen“, „Anhänge“</li><li>Netzknoten und Adresse: „Eigenschaften“, „Aktionen“, „Anhänge“</li><li>Gebiet: „Eigenschaften“, „Anhänge“</li></ul><p>Die Angaben im Reiter „Eigenschaften“ sind hier nicht bearbeitbar, sondern dienen als Informationsquelle. Bearbeiten können Sie in der Karte ausschließlich den Reiter „Anhänge“, siehe Abschnitt <a href="#_5-8-anhange-an-einem-kartenobjekt">Anhänge an einem Kartenobjekt</a>.</p><p><img src="'+s+'" alt="Screenshot Karte mit Hervorhebung eines ausgewählten Objekts und der Anzeige der Details in der Info-Box rechts" data-zoomable="true"></p><h2 id="_5-4-rohrubersicht-und-kabelubersicht-einer-trasse" tabindex="-1">5.4 Rohrübersicht und Kabelübersicht einer Trasse <a class="header-anchor" href="#_5-4-rohrubersicht-und-kabelubersicht-einer-trasse" aria-label="Permalink to &quot;5.4 Rohrübersicht und Kabelübersicht einer Trasse&quot;">​</a></h2><p>Der Reiter „Rohrübersicht“ zeigt die Rohre der ausgewählten Trasse, siehe Kapitel <a href="./10-rohrverwaltung.html">Rohrverwaltung</a>, „Kabelübersicht“ die darin liegenden Kabel.</p><p><strong>Rohrübersicht</strong></p><p>Jedes Rohr steht als eigene Zeile mit seinem Namen und dem Rohrtyp in Klammern. Ein Klick auf die Zeile klappt sie auf und lädt die Mikrorohre des Rohrs; die Liste ist dieselbe wie im Reiter „Status“ der Rohrverwaltung, hier aber nicht bearbeitbar, siehe Abschnitt <a href="./10-rohrverwaltung.html#_10-4-mikrorohre-eines-rohrs">Mikrorohre eines Rohrs</a>. Mehrere Zeilen lassen sich gleichzeitig geöffnet halten. Liegt in der Trasse kein Rohr, steht dort „Keine Rohre gefunden“.</p><p><img src="'+d+'" alt="Screenshot der Info-Box einer Trasse im Reiter „Rohrübersicht“ mit einem aufgeklappten Rohr und der Liste seiner Mikrorohre" class="big" data-zoomable="true"></p><p>Die Schaltfläche „Trassen auf Karte hervorheben“ in der Zeile eines Rohrs markiert alle Trassen, durch die dieses Rohr verläuft. So verfolgen Sie seinen Verlauf über die ausgewählte Trasse hinaus.</p><p><strong>Kabelübersicht</strong></p><p>Die Kabelübersicht ist ebenso aufgebaut: je Kabel eine Zeile mit Namen, Kabeltyp und der Zahl der Fasern. Aufgeklappt stehen darin die <strong>Bündel</strong> des Kabels, jedes mit seiner Farbe, seiner Nummer und der Zahl seiner Fasern; sind Fasern als defekt vermerkt, steht ihre Anzahl am rechten Rand des Bündels. Ein Klick auf ein Bündel zeigt dessen Fasern mit „#“, „Farbe“ und „Status“.</p><p><img src="'+l+'" alt="Screenshot der Info-Box einer Trasse im Reiter „Kabelübersicht“ mit einem aufgeklappten Kabel und den Fasern des ersten Bündels" class="big" data-zoomable="true"></p><p>Jede Kabelzeile trägt zwei Schaltflächen: „Trassen auf Karte hervorheben“ wie bei den Rohren und „Folgen“, das den Faserweg dieses Kabels öffnet, siehe Abschnitt <a href="#_5-7-von-der-karte-in-den-faserweg-wechseln">Von der Karte in den Faserweg wechseln</a>. Dieselbe Schaltfläche „Folgen“ gibt es an jeder einzelnen Faser. Liegt in der Trasse kein Kabel, steht dort „Keine Kabel in dieser Trasse“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Den Status einer Faser ändern Sie im Netzschema, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>.</p></div><h2 id="_5-5-grabenprofil-einer-trasse" tabindex="-1">5.5 Grabenprofil einer Trasse <a class="header-anchor" href="#_5-5-grabenprofil-einer-trasse" aria-label="Permalink to &quot;5.5 Grabenprofil einer Trasse&quot;">​</a></h2><p>Im Reiter „Aktionen“ einer Trasse öffnet „Grabenprofil anzeigen“ den Querschnitt des Grabens mit der Lage der Rohre.</p><p>Das <strong>Grabenprofil</strong> erscheint in einem eigenen Fenster über der Karte. Es zeigt den Graben im Schnitt mit seinen Bodenschichten und darin je Rohr einen Kreis. Im Kreis stehen die Mikrorohre des Rohrs in ihren Farben, zweifarbige geteilt dargestellt; Mikrorohre mit einem hinterlegten Status sind blasser und mit einem ✕ gekennzeichnet. Unter jedem Kreis steht der Name des Rohrs, ein Zeigen mit der Maus nennt zusätzlich den Rohrtyp.</p><p><img src="'+h+'" alt="Screenshot des Fensters „Grabenprofil“ über der Karte mit drei Rohren im Querschnitt" class="big" data-zoomable="true"></p><p>Über die Schaltflächen links unten im Fenster zoomen Sie in die Zeichnung hinein und heraus und richten sie wieder auf ihren Inhalt aus. Das Fenster selbst verschieben Sie an seiner Titelzeile, an der rechten unteren Ecke ändern Sie seine Größe; die Schaltflächen in der Titelzeile verkleinern, maximieren und schließen es.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Das Profil ist eine schematische Darstellung, keine maßstäbliche Bauzeichnung: Die Rohre werden gleichmäßig angeordnet, ihre Lage im Bild entspricht nicht ihrer Lage im Graben. Verschieben lassen sie sich hier nicht.</p></div><p>Enthält die Trasse keine Rohre, steht im Fenster „Keine Leerrohre in diesem Graben gefunden“.</p><h2 id="_5-6-netzknoten-slot-konfiguration-und-struktur-offnen" tabindex="-1">5.6 Netzknoten: Slot-Konfiguration und Struktur öffnen <a class="header-anchor" href="#_5-6-netzknoten-slot-konfiguration-und-struktur-offnen" aria-label="Permalink to &quot;5.6 Netzknoten: Slot-Konfiguration und Struktur öffnen&quot;">​</a></h2><p>Im Reiter „Aktionen“ eines Netzknotens führen „Slot-Konfiguration anzeigen“ und „Struktur anzeigen“ zu dessen innerem Aufbau. Beide öffnen ein eigenes Fenster über der Karte, das sich wie das Grabenprofil verschieben und in der Größe ändern lässt.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Beide Fenster öffnen mittig und sind gleich groß, und „Netzknotenstruktur“ liegt immer über „Netzknoten-Konfiguration“ – unabhängig davon, welches Sie zuerst geöffnet haben. Sobald die Struktur offen ist, verdeckt sie die Konfiguration vollständig; diese ist nicht geschlossen, sondern nur nicht zu sehen. Ziehen Sie das obere Fenster an seiner Titelzeile beiseite, dann liegen beide nebeneinander; ein Klick auf ein Fenster holt es nach vorn.</p><p>Erst dann sehen Sie auch, was „Struktur anzeigen“ in der Konfiguration bewirkt: Es schaltet das bereits geöffnete Strukturfenster auf die gewählte Seite um, holt es aber nicht nach vorn.</p></div><p><strong>Slot-Konfiguration</strong></p><p>Das Fenster „Netzknoten-Konfiguration“ listet die Einbauplätze des Netzknotens auf, je Seite eine Konfiguration; sind für das Projekt Container eingerichtet, sind die Konfigurationen darin gruppiert. Zu jeder Konfiguration stehen die Seite sowie „Gesamtslots“, „Belegt“ und „Frei“ – so sehen Sie, wie viel Platz im Netzknoten noch ist. Die Schaltfläche „Struktur anzeigen“ an einer Konfiguration führt direkt in deren Belegung. Das Download-Symbol oben rechts speichert den Aufbau des Netzknotens als Excel-Datei, siehe Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-8-exportformate-im-uberblick">Exportformate im Überblick</a>.</p><p><img src="'+o+'" alt="Screenshot des Fensters „Netzknoten-Konfiguration“ mit den beiden Konfigurationen A und B des Netzknotens" class="big" data-zoomable="true"></p><p>Sind für den Netzknoten keine Einbauplätze hinterlegt, steht dort „Keine Slot-Konfigurationen gefunden“.</p><p><strong>Struktur</strong></p><p>Das Fenster „Netzknotenstruktur“ zeigt die Belegung einer Seite. Es ist zweigeteilt: links das <strong>Slot-Grid</strong>, rechts die Leiste „Kabel“.</p><p><img src="'+u+'" alt="Screenshot des Fensters „Netzknotenstruktur“ mit dem Slot-Grid links und der Kabelleiste rechts" class="big" data-zoomable="true"></p><p>Über dem Slot-Grid wählen Sie unter „Seite auswählen“, welche Konfiguration Sie sehen; daneben steht die Zahl der Gesamtslots. Das Grid selbst hat drei Spalten: „TPU“ mit der Nummer des Einbauplatzes, „Komponente“ mit dem dort eingebauten Bauteil und „Clip“ mit dessen Clip-Nummer. Eine Komponente, die mehrere Slots belegt – ein Splitter etwa zwei –, steht als ein Block über deren Zeilen; freie Slots zeigen einen Strich.</p><p>Ein Klick auf eine Komponente öffnet deren Ports mit den Spalten „Port“, „Faser A“ und „Faser B“, also den beiderseits aufgelegten Fasern. „Zurück“ führt wieder zum Grid. Sind für die Komponente keine Ports hinterlegt, steht dort „Keine Ports für diese Komponente konfiguriert“.</p><p>Die Leiste „Kabel“ am rechten Rand führt alle Kabel des Netzknotens auf, je Eintrag den Namen und die Zahl der Fasern; ein Pfeil dahinter zeigt, ob das Kabel am Netzknoten beginnt oder endet. Ein Klick auf ein Kabel klappt seine Bündel auf, ein Klick auf ein Bündel dessen Fasern. Zu jeder Faser stehen ihre Farbe und ihre durchlaufende Nummer, und wenn sie auf einer Komponente aufliegt, deren Bezeichnung. Defekte Fasern sind durchgestrichen; ein Zeigen mit der Maus nennt den Status. Sind dem Netzknoten Adressen zugeordnet, folgt unter den Kabeln der Abschnitt „Adressen“ mit deren Wohneinheiten.</p><p>Am linken Rand der Leiste ziehen Sie sie über den Griff „Größe der Seitenleiste ändern“ breiter oder schmaler; die runde Schaltfläche „Einklappen“ an ihrer oberen linken Ecke klappt sie zu einem schmalen Streifen zusammen, „Erweitern“ holt sie zurück. Hat der Netzknoten keine Kabel, steht dort „Keine Kabel an diesem Netzknoten“.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Aus der Karte heraus sind beide Fenster reine Anzeigen. Angelegt und verändert wird der Aufbau eines Netzknotens im Netzschema, siehe Kapitel <a href="./14-netzschema.html">Netzschema</a>.</p></div><h2 id="_5-7-von-der-karte-in-den-faserweg-wechseln" tabindex="-1">5.7 Von der Karte in den Faserweg wechseln <a class="header-anchor" href="#_5-7-von-der-karte-in-den-faserweg-wechseln" aria-label="Permalink to &quot;5.7 Von der Karte in den Faserweg wechseln&quot;">​</a></h2><p>Im Reiter „Aktionen“ eines Netzknotens oder einer Adresse springt „Folgen“ in die Ansicht „Faserweg“, siehe Kapitel <a href="./15-faserweg.html">Faserweg</a>.</p><p>Der Faserweg wird dabei sofort für das ausgewählte Objekt ermittelt: von einem Netzknoten aus für alle Fasern, die durch ihn laufen, von einer Adresse aus für die Fasern der dort angeschlossenen Netzknoten und Wohneinheiten. Dieselbe Schaltfläche „Folgen“ finden Sie im Reiter „Kabelübersicht“ an jedem Kabel und an jeder einzelnen Faser, siehe Abschnitt <a href="#_5-4-rohrubersicht-und-kabelubersicht-einer-trasse">Rohrübersicht und Kabelübersicht einer Trasse</a>.</p><p>„Folgen“ verlässt die Karte. Über die Zurück-Funktion des Browsers oder den Menüpunkt „Karte“ kehren Sie zurück; der Kartenausschnitt bleibt erhalten, die Info-Box öffnet sich nicht erneut.</p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Lässt sich zu dem gewählten Objekt kein Faserweg ermitteln, etwa weil noch kein Kabel angeschlossen ist, zeigt die Ansicht „Faserweg“ statt eines Ergebnisses eine Fehlermeldung mit der Kennung des Objekts.</p></div><h2 id="_5-8-anhange-an-einem-kartenobjekt" tabindex="-1">5.8 Anhänge an einem Kartenobjekt <a class="header-anchor" href="#_5-8-anhange-an-einem-kartenobjekt" aria-label="Permalink to &quot;5.8 Anhänge an einem Kartenobjekt&quot;">​</a></h2><p>Zu jedem Kartenobjekt können Sie Dateien ablegen. Hochladen, Herunterladen, Umbenennen und Löschen funktionieren wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a> beschrieben.</p><h2 id="_5-9-grenzen-der-darstellung" tabindex="-1">5.9 Grenzen der Darstellung <a class="header-anchor" href="#_5-9-grenzen-der-darstellung" aria-label="Permalink to &quot;5.9 Grenzen der Darstellung&quot;">​</a></h2><p>Ein Klick auf eine freie Stelle der Karte hebt die Auswahl auf – innerhalb eines Projektgebiets ist das allerdings kaum möglich, weil dessen Fläche die gesamte Umgebung überdeckt; schließen Sie die Info-Box dann über das Kreuz „Seitenleiste schließen“.</p><p>Warum ein Klick oft nicht das gewünschte Objekt trifft und was dagegen hilft, beschreibt Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-3-das-kartenfenster">Das Kartenfenster</a> unter „Objekte anklicken“.</p>',58)])])}const S=n(c,[["render",b]]);export{z as __pageData,S as default};
